10	#ifndef ATVOSS_ARGUMENTS_H
11	#define ATVOSS_ARGUMENTS_H
12	
13	#include <tuple>
14	#include <string>
15	#include <type_traits>
16	#include <vector>
17	#include "utils/utility.h"
18	
19	namespace Atvoss {
20	
21	template <typename Key, typename Value>
22	struct AttrMap {
23	    Key key;
24	    Value value;
25	};
26	
27	template <typename Key, typename Value>
28	constexpr auto MakeAttr(Key key, Value value)
29	{
30	    return AttrMap<Key, Value>{key, value};
31	}
32	
33	template <typename Tuple1, typename Tuple2>
34	struct ConcatTuples;
35	
36	template <typename... T1, typename... T2>
37	struct ConcatTuples<std::tuple<T1...>, std::tuple<T2...>> {
38	    using type = std::tuple<T1..., T2...>;
39	};
40	
41	template <typename Tuple1, typename Tuple2>
42	using ConcatTuplesT = typename ConcatTuples<Tuple1, Tuple2>::type;
43	
44	template <typename InputOutputTuple>
45	struct InputOutputCollector {
46	    InputOutputTuple inputOutput;
47	
48	    template <typename... NewInputOutput>
49	    constexpr auto AddInputOutput(NewInputOutput&... newInputOutput) const
50	    {
51	        auto newTuple = std::tuple_cat(inputOutput, std::forward_as_tuple(newInputOutput...));
52	        using NewInputOutputTuple = ConcatTuplesT<InputOutputTuple, std::tuple<NewInputOutput&...>>;
53	        return InputOutputCollector<NewInputOutputTuple>{newTuple};
54	    }
55	};
56	
57	template <typename AttrsTuple>
58	struct AttrCollector {
59	    AttrsTuple attrs;
60	
61	    template <typename Key, typename Value>
62	    constexpr auto AddAttr(Key key, Value value) const
63	    {
64	        auto newTuple = std::tuple_cat(attrs, std::make_tuple(MakeAttr(key, value)));
65	        using NewAttrsTuple = ConcatTuplesT<AttrsTuple, std::tuple<AttrMap<Key, Value>>>;
66	        return AttrCollector<NewAttrsTuple>{newTuple};
67	    }
68	};
69	
70	template <typename InOutCollector, typename AttrCollector>
71	struct ArgumentsBuilderImpl {
72	    InOutCollector inOutCollector;
73	    AttrCollector attrCollector;
74	
75	    ArgumentsBuilderImpl(InOutCollector ic, AttrCollector ac) : inOutCollector(ic), attrCollector(ac)
76	    {}
77	
78	    template <typename... NewInputOutput>
79	    constexpr auto inputOutput(NewInputOutput&... newInputOutput) const
80	    {
81	        auto newInOutCollector = inOutCollector.AddInputOutput(newInputOutput...);
82	        return ArgumentsBuilderImpl<decltype(newInOutCollector), AttrCollector>{newInOutCollector, attrCollector};
83	    }
84	
85	    template <typename Key, typename Value>
86	    constexpr auto attr(Key key, Value value) const
87	    {
88	        auto newAttrCollector = attrCollector.AddAttr(key, value);
89	        return ArgumentsBuilderImpl<InOutCollector, decltype(newAttrCollector)>{inOutCollector, newAttrCollector};
90	    }
91	
92	    constexpr auto build() const
93	    {
94	        return std::make_tuple(inOutCollector.inputOutput, attrCollector.attrs);
95	    }
96	};
97	
98	template <typename InOutCollector, typename AttrCollector>
99	ArgumentsBuilderImpl(InOutCollector, AttrCollector) -> ArgumentsBuilderImpl<InOutCollector, AttrCollector>;
100	
101	struct ArgumentsBuilder {
102	    template <typename... InitialInputOutput>
103	    constexpr auto inputOutput(InitialInputOutput&&... inputOutput) const
104	    {
105	        // 参数必须为Tensor和非指针类的scalar类型
106	        static_assert(
107	            (... && !std::is_pointer_v<InitialInputOutput>), "Pointer types are not allowed in inputOutput parameters");
108	        static_assert(
109	            (... && (Util::IsSpecializationOf_v<Atvoss::Tensor, std::decay_t<InitialInputOutput>> ||
110	                     std::is_scalar_v<std::decay_t<InitialInputOutput>>)),
111	            "Only Atvoss::Tensor and scalar types are allowed in inputOutput parameters");
112	
113	        auto initialInputOutput = std::forward_as_tuple(inputOutput...);
114	        auto inOutCollector = InputOutputCollector<std::tuple<InitialInputOutput&...>>{initialInputOutput};
115	        auto attrCollector = AttrCollector<std::tuple<>>{};
116	
117	        return ArgumentsBuilderImpl{inOutCollector, attrCollector};
118	    }
119	
120	    template <typename Key, typename Value>
121	    constexpr auto attr(Key key, Value value) const
122	    {
123	        auto inOutCollector = InputOutputCollector<std::tuple<>>{};
124	        auto initialAttrs = std::make_tuple(MakeAttr(key, value));
125	        auto attrCollector = AttrCollector<std::tuple<AttrMap<Key, Value>>>{initialAttrs};
126	
127	        return ArgumentsBuilderImpl{inOutCollector, attrCollector};
128	    }
129	};
130	} // namespace Atvoss
131	#endif // ATVOSS_ARGUMENTS_H

